namespace EnhancedSchoolsMod\n{\n    public class SchoolTerm\n    {\n        public string Season { get; set; } = \"Spring\";\n        public int StartDay { get; set; } = 1;\n        public int EndDay { get; set; } = 28;\n        public string HolidayName { get; set; } = \"\";\n        public int HolidayStartDay { get; set; } = 0;\n        public int HolidayEndDay { get; set; } = 0;\n        public bool IsWithinTerm(int day) => day >= StartDay && day <= EndDay;\n        public bool IsWithinHoliday(int day) => HolidayStartDay > 0 && day >= HolidayStartDay && day <= HolidayEndDay;\n        public int DaysUntilHoliday(int currentDay) => currentDay >= HolidayStartDay ? -1 : HolidayStartDay - currentDay;\n    }\n}